import { test, expect } from '@playwright/test';

test.describe('Table Loading State', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000');
  });

  test('should display loading skeleton when table data is fetching', async ({ page }) => {
    // Navigate to a page that triggers table data fetch
    await page.goto('http://localhost:3000/table');

    // Verify loading state is visible immediately
    const loadingIndicator = page.getByRole('status');
    await expect(loadingIndicator).toBeVisible();

    // Verify loading text is present
    const loadingText = page.getByText(/loading|fetching/i);
    await expect(loadingText).toBeVisible();

    // Verify table is not yet visible during loading
    const table = page.getByRole('table');
    await expect(table).not.toBeVisible();
  });

  test('should hide loading state and display table after data loads', async ({ page }) => {
    await page.goto('http://localhost:3000/table');

    // Wait for loading state to appear first
    const loadingIndicator = page.getByRole('status');
    await expect(loadingIndicator).toBeVisible();

    // Wait for loading state to disappear
    await expect(loadingIndicator).not.toBeVisible({ timeout: 10000 });

    // Verify table is now visible
    const table = page.getByRole('table');
    await expect(table).toBeVisible();

    // Verify table has rows with data
    const rows = page.getByRole('row');
    const rowCount = await rows.count();
    expect(rowCount).toBeGreaterThan(0);
  });

  test('should display loading spinner with proper accessibility attributes', async ({ page }) => {
    await page.goto('http://localhost:3000/table');

    // Verify loading indicator has proper ARIA attributes
    const loadingSpinner = page.getByRole('status');
    await expect(loadingSpinner).toHaveAttribute('aria-live', 'polite');

    // Verify loading message is accessible
    const loadingMessage = page.getByText(/loading|fetching/i);
    await expect(loadingMessage).toBeVisible();

    // Verify aria-busy attribute on table container during loading
    const tableContainer = page.locator('[role="region"]');
    if (await tableContainer.isVisible()) {
      const ariaBusy = await tableContainer.getAttribute('aria-busy');
      expect(['true', 'false']).toContain(ariaBusy);
    }
  });

  test('should show loading state when refreshing table data', async ({ page }) => {
    await page.goto('http://localhost:3000/table');

    // Wait for initial load to complete
    await expect(page.getByRole('status')).not.toBeVisible({ timeout: 10000 });
    await expect(page.getByRole('table')).toBeVisible();

    // Click refresh button
    const refreshButton = page.getByRole('button', { name: /refresh|reload/i });
    if (await refreshButton.isVisible()) {
      await refreshButton.click();

      // Verify loading state appears again
      const loadingIndicator = page.getByRole('status');
      await expect(loadingIndicator).toBeVisible({ timeout: 5000 });

      // Verify loading state disappears after refresh
      await expect(loadingIndicator).not.toBeVisible({ timeout: 10000 });

      // Verify table is still visible after refresh
      const table = page.getByRole('table');
      await expect(table).toBeVisible();
    }
  });

  test('should display loading skeleton with correct number of placeholder rows', async ({ page }) => {
    await page.goto('http://localhost:3000/table');

    // Get loading skeleton rows
    const skeletonRows = page.locator('[data-testid="skeleton-row"]');
    const skeletonCount = await skeletonRows.count();

    // Verify skeleton rows are visible during loading
    if (skeletonCount > 0) {
      await expect(skeletonRows.first()).toBeVisible();

      // Verify skeleton rows have proper styling/animation
      const firstSkeletonRow = skeletonRows.first();
      const hasAnimationClass = await firstSkeletonRow.evaluate((el) => {
        return el.className.includes('skeleton') || el.className.includes('loading');
      });
      expect(hasAnimationClass).toBeTruthy();
    }

    // Wait for actual data to load
    await expect(page.getByRole('status')).not.toBeVisible({ timeout: 10000 });

    // Verify skeleton rows are replaced with actual data
    const dataRows = page.getByRole('row');
    await expect(dataRows.first()).toBeVisible();
  });

  test('should maintain loading state during slow network conditions', async ({ page, context }) => {
    // Simulate slow network
    await context.route('**/api/**', async (route) => {
      await new Promise(resolve => setTimeout(resolve, 2000));
      await route.continue();
    });

    await page.goto('http://localhost:3000/table');

    // Verify loading state is visible for extended period
    const loadingIndicator = page.getByRole('status');
    await expect(loadingIndicator).toBeVisible();

    // Wait a bit and verify still loading
    await page.waitForTimeout(1000);
    await expect(loadingIndicator).toBeVisible();

    // Eventually should load
    await expect(loadingIndicator).not.toBeVisible({ timeout: 15000 });
    await expect(page.getByRole('table')).toBeVisible();
  });
});
